### Throttle decorator

@decorator
def throttle(call, rate=None, per=None, max_calls=None):
    """Throttles a function call rate.

    Args:
        rate: Maximum number of calls per time period
        per: Time period (int for seconds, or timedelta)
        max_calls: Maximum number of calls allowed
    """
    import time

    if per is not None and isinstance(per, int):
        per = timedelta(seconds=per)

    last_call_time = [None]
    call_count = [0]

    def wrapper():
        now = time.monotonic()

        if per is not None:
            if last_call_time[0] is not None:
                elapsed = now - last_call_time[0]
                per_seconds = per.total_seconds() if hasattr(per, 'total_seconds') else per
                if elapsed < per_seconds:
                    raise Exception("Rate limited")

        if max_calls is not None:
            if call_count[0] >= max_calls:
                raise Exception("Max calls exceeded")
            call_count[0] += 1

        last_call_time[0] = now
        return call()


def process_beat(rate, per=60):
    """Creates a throttling configuration based on rate and period."""
    if isinstance(per, int):
        per = timedelta(seconds=per)
    return {"rate": rate, "per": per}


def rate_limit(fails=10, timeout=60, exception=ErrorRateExceeded):
    """Rate limiting decorator. Alias for limit_error_rate."""
    if isinstance(timeout, int):
        timeout = timedelta(seconds=timeout)
    return limit_error_rate(fails, timeout, exception)


def throttle(fails=10, timeout=60, exception=ErrorRateExceeded):
    """Throttle function calls based on error rate. Alias for limit_error_rate."""
    if isinstance(timeout, int):
        timeout = timedelta(seconds=timeout)
    return limit_error_rate(fails, timeout, exception)

